"""Build the self-contained SwiftLog analytical dashboard."""
from pathlib import Path
import json
import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
tables = {}
for name in ['Orders','OrderItems','Shipments','Inventory','Employees','Products','Warehouses','Customers','Suppliers']:
    frame = pd.read_csv(ROOT / 'Data' / 'Processed' / (name + '.csv'))
    tables[name] = frame.to_dict('records')
tables['Returns'] = pd.read_csv(ROOT / 'Data' / 'Original_Datasets' / 'SwiftLog_Returns.csv').to_dict('records')
payload = json.dumps(tables, separators=(',',':'))
page = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>SwiftLog Logistics Analytics</title><style>
:root{--navy:#142f43;--teal:#137d7b;--gold:#ce8c29;--red:#bf4a3c;--ink:#243746;--muted:#587082;--paper:#f1f5f7;--line:#d8e3e8}
*{box-sizing:border-box}body{margin:0;font:15px Arial,sans-serif;background:var(--paper);color:var(--ink)}
header{background:var(--navy);color:white;padding:22px 34px}header h1{font-size:29px;margin:0 0 8px}header p{margin:0;color:#c5d8e3;font-size:14px}
nav{display:flex;gap:7px;padding:13px 30px;background:white;flex-wrap:wrap;border-bottom:1px solid var(--line)}button,select{font:inherit;cursor:pointer}nav button{border:0;border-radius:4px;background:#eef4f6;padding:11px 17px;color:var(--ink)}nav button.active{background:var(--teal);color:white}
.filters{display:flex;gap:12px;flex-wrap:wrap;padding:16px 32px;background:white;align-items:end}.filters label{font-size:12px;display:grid;gap:6px;color:var(--muted)}select{min-width:138px;padding:9px;border:1px solid #c6d5dd;border-radius:4px;color:var(--ink);background:white}.filters button{padding:9px;border:1px solid #b9cbd4;background:#fff;border-radius:4px}
main{max-width:1540px;margin:auto;padding:17px 32px 26px}.page-title{display:flex;align-items:baseline;gap:14px;flex-wrap:wrap;margin:0 0 14px}.page-title h2{font-size:23px;margin:0}.context{font-size:13px;color:var(--muted)}
.kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-bottom:15px}.kpi{border-top:3px solid var(--teal);padding:13px 15px;background:white}.kpi b{display:block;font-size:27px;font-weight:700;margin:6px 0}.kpi small{font-size:11px;color:var(--muted)}.kpi span{font-size:12px;color:var(--muted)}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.panel{background:white;border:1px solid var(--line);padding:17px 19px;min-width:0}.panel h3{margin:0 0 14px;font-size:17px}.note{font-size:12px;color:var(--muted);line-height:1.45;margin:12px 0 0}.bars{display:grid;gap:8px}.bar{display:grid;grid-template-columns:105px 1fr 87px;gap:9px;align-items:center;min-height:22px;font-size:12px}.bar label{overflow-wrap:anywhere}.track{height:17px;background:#eaf1f4}.fill{height:100%;background:var(--teal);min-width:1px}.bar strong{text-align:right;font-size:12px;font-weight:500}.bar[data-click]{cursor:pointer}.bar[data-click]:hover{color:#00736b}.orange .fill{background:var(--gold)}.red .fill{background:var(--red)}
.callout{background:#eef6f5;border-left:3px solid var(--teal);padding:12px 15px;line-height:1.55;font-size:13px;margin-top:15px}.limited{color:#8a531b;background:#fff8eb}.small-table{border-collapse:collapse;width:100%;font-size:12px}.small-table th,.small-table td{text-align:left;border-bottom:1px solid var(--line);padding:8px 7px}.small-table th{color:var(--muted);font-weight:600}.threshold{display:flex;gap:12px;align-items:center;margin-bottom:16px}.threshold input{max-width:290px;flex:1}footer{font-size:12px;color:var(--muted);margin-top:17px;padding-top:12px;border-top:1px solid var(--line)}dialog{border:1px solid var(--line);border-radius:8px;padding:24px;max-width:650px;width:92vw}dialog::backdrop{background:#142f4377}dialog button{float:right;padding:8px 13px}.empty{font-size:14px;color:var(--muted);padding:24px 0}#saved{font-size:12px;color:var(--teal)}
@media(max-width:750px){header{padding:20px}header h1{font-size:25px}nav,.filters{padding:12px 16px;gap:8px}nav button{padding:10px;font-size:12px}.filters label{flex:1}select{min-width:0;width:100%}main{padding:16px}.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.kpi:last-child{grid-column:span 2}.kpi b{font-size:25px}.grid{grid-template-columns:1fr}.bar{grid-template-columns:85px 1fr 76px}.panel{padding:17px}.small-table{font-size:11px}.small-table td,.small-table th{padding:7px 4px}}
</style></head><body>
<header><h1>SwiftLog Logistics Analytics</h1><p>Supply chain performance and business intelligence · 1 January - 8 September 2026</p></header>
<nav id="nav"></nav><section class="filters">
<label>Order month<select id="month"></select></label><label>Customer city<select id="city"></select></label>
<label>Warehouse<select id="warehouse"></select></label><label>Product category<select id="category"></select></label><label>Order status<select id="status"></select></label>
<button id="reset">Reset filters</button><button id="save">Save view</button><button id="restore">Restore view</button><span id="saved" role="status"></span>
</section><main><div class="page-title"><h2 id="title"></h2><span class="context" id="context"></span></div><div id="content"></div>
<footer>Iyiola Anjolaoluwa Emmanuel · AnalystLab Africa · Week 5<br>Values use supplied catalogue prices. Currency and revenue recognition are unspecified. Inventory is an aggregate quantity proxy. Source: provided SwiftLog datasets.</footer></main>
<dialog id="detail"><button onclick="this.closest('dialog').close()">Close</button><div id="detail-body"></div></dialog>
<script>const DATA = ''' + payload + r''';
const pages=['Executive','Customers','Inventory & Warehouses','Shipments & Delivery','Suppliers & Products'];let active=0,threshold=100;
const $=id=>document.getElementById(id);const number=(x,d=0)=>Number.isFinite(Number(x))?Number(x).toLocaleString('en-GB',{minimumFractionDigits:d,maximumFractionDigits:d}):'N/A';const percent=x=>Number.isFinite(x)?number(100*x,2)+'%':'N/A';const sum=(a,k)=>a.reduce((s,r)=>s+Number(r[k]||0),0);const distinct=(a,k)=>new Set(a.map(r=>r[k])).size;
const unique=(t,k)=>[...new Set(DATA[t].map(r=>r[k]))].sort();
for(const [id,values]of [['month',unique('Orders','Month')],['city',unique('Customers','City')],['warehouse',unique('Warehouses','WarehouseID')],['category',unique('Products','Category')],['status',unique('Orders','Status')]]){$(id).innerHTML='<option value="">All</option>'+values.map(v=>`<option>${v}</option>`).join('');$(id).onchange=render;}
$('nav').innerHTML=pages.map((p,i)=>`<button data-page="${i}" onclick="active=${i};render()">${p}</button>`).join('');
function filters(){return Object.fromEntries(['month','city','warehouse','category','status'].map(k=>[k,$(k).value]));}
function subset(){const f=filters();let o=DATA.Orders.filter(r=>(!f.month||r.Month===f.month)&&(!f.city||r.City===f.city)&&(!f.status||r.Status===f.status));if(f.warehouse){const ids=new Set(DATA.Shipments.filter(r=>r.WarehouseID===f.warehouse).map(r=>r.OrderID));o=o.filter(r=>ids.has(r.OrderID));}if(f.category){const ids=new Set(DATA.OrderItems.filter(r=>r.Category===f.category).map(r=>r.OrderID));o=o.filter(r=>ids.has(r.OrderID));}const ids=new Set(o.map(r=>r.OrderID));return{o,i:DATA.OrderItems.filter(r=>ids.has(r.OrderID)&&(!f.category||r.Category===f.category)),s:DATA.Shipments.filter(r=>ids.has(r.OrderID)),v:DATA.Inventory.filter(r=>(!f.warehouse||r.WarehouseID===f.warehouse)&&(!f.category||DATA.Products.find(p=>p.ProductID===r.ProductID).Category===f.category))};}
function group(rows,key,value,mode='sum'){const out=new Map();for(const r of rows){const k=r[key];if(!out.has(k))out.set(k,{key:k,value:0,count:0,ids:new Set()});const z=out.get(k);z.count++;z.value+=value?Number(r[value]||0):1;z.ids.add(r.OrderID);}return [...out.values()].map(z=>({key:z.key,value:mode==='mean'?z.value/z.count:mode==='distinct'?z.ids.size:z.value,count:z.count}));}
function bars(rows,{pct=false,dec=0,click='',color=''}={}){if(!rows.length)return '<div class="empty">No records in this selection.</div>';const max=Math.max(...rows.map(r=>r.value),1);return `<div class="bars ${color}">`+rows.map(r=>{const txt=pct?percent(r.value):number(r.value,dec);const event=click?` data-click="${click}" onclick="drill('${click}','${r.key}')"`:'';return `<div class="bar"${event} title="${r.key}: ${txt} (${number(r.count)} records)"><label>${r.key}</label><div class="track"><div class="fill" style="width:${Math.max(0,100*r.value/max)}%"></div></div><strong>${txt}</strong></div>`;}).join('')+'</div>';}
function card(label,value,note=''){return `<div class="kpi"><span>${label}</span><b>${value}</b><small>${note}</small></div>`;}function panel(title,body,note=''){return `<section class="panel"><h3>${title}</h3>${body}${note?`<p class="note">${note}</p>`:''}</section>`;}
function grid(...p){return `<div class="grid">${p.join('')}</div>`;}function top(rows,n=8){return rows.sort((a,b)=>b.value-a.value||String(a.key).localeCompare(String(b.key))).slice(0,n);}
function table(headers,rows){return `<table class="small-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')}</tbody></table>`;}
function render(){const {o,i,s,v}=subset(),f=filters();document.querySelectorAll('nav button').forEach((b,n)=>b.classList.toggle('active',n===active));$('title').textContent=pages[active];$('context').textContent=Object.values(f).filter(Boolean).join(' / ')||'All records';const delivered=i.filter(r=>r.Status==='Delivered'),priced=distinct(delivered,'OrderID'),value=sum(delivered,'LineValue'),ret=o.filter(r=>r.HasReturn),on=sum(s,'RecordedOnTime');let html='';
if(active===0){html='<div class="kpis">'+card('Orders',number(o.length))+card('Delivered order value',number(value/1e6,2)+'m','Catalogue price units')+card('Recorded on-time',percent(on/s.length),'Source status: delay 0-2 days')+card('Orders with returns',percent(ret.length/o.length),number(ret.length)+' distinct orders')+card('Priced delivered AOV',number(value/priced,2),number(priced)+' priced delivered orders')+'</div>';
html+=grid(panel('Delivered order value by order month',bars(group(delivered,'Month','LineValue').sort((a,b)=>a.key.localeCompare(b.key)),{dec:0}),'September covers eight days.'),panel('Monthly order volume',bars(group(o,'Month').sort((a,b)=>a.key.localeCompare(b.key)))));
html+='<div style="height:15px"></div>'+grid(panel('Recorded delivery status',bars(group(s,'DeliveryStatus'),{color:'orange'}),'A positive delay can still carry the recorded On Time label.'),panel('Return reasons',bars(group(DATA.Returns.filter(r=>new Set(o.map(x=>x.OrderID)).has(r.OrderID)),'Reason')),'Counts show return events. Repeated events belong to the same order.'));
html+='<div class="callout">Catalogue coverage: '+number(o.filter(r=>r.HasItems).length)+' of '+number(o.length)+' orders have item records. The order-date filter defines shipment and return cohorts. Delivery duration, supplier performance, capacity utilisation and standard inventory turnover cannot be estimated from the supplied fields.</div>';}
if(active===1){const byCustomer=group(o,'CustomerID');html='<div class="kpis">'+card('Active customers',number(distinct(o,'CustomerID')))+card('Orders per active customer',number(o.length/distinct(o,'CustomerID'),2))+card('Repeat customers',percent(byCustomer.filter(r=>r.value>1).length/byCustomer.length),'More than one selected order')+card('Delivered value',number(value/1e6,2)+'m','Catalogue price units')+card('Customer base',number(DATA.Customers.length),'Full source catalogue')+'</div>';
html+=grid(panel('Top customers by delivered value',bars(top(group(delivered,'CustomerID','LineValue')),{dec:0,click:'customer'}),'Select a customer for order details.'),panel('Orders by customer city',bars(top(group(o,'City')),{click:'city'}),'Select a city to filter all pages. City is a destination proxy.'));
html+='<div style="height:15px"></div>'+grid(panel('Customer order frequency',bars(group(byCustomer.map(r=>({Band:r.value>=8?'8+ orders':r.value<=2?'1-2 orders':r.value<=4?'3-4 orders':'5-7 orders'})),'Band'))),panel('First observed customers by month',bars(group(o.filter(r=>r.IsFirstObservedOrder),'Month').sort((a,b)=>a.key.localeCompare(b.key))),'First appearance in the supplied order history does not establish acquisition date or retention.'));}
if(active===2){const products=distinct(v,'ProductID'),low=v.filter(r=>r.Stock<threshold),ws=group(v,'WarehouseID','Stock');html='<div class="threshold"><label for="threshold">Low-stock planning threshold</label><input id="threshold" type="range" min="0" max="500" step="25" value="'+threshold+'" oninput="threshold=Number(this.value);render()"><strong>'+number(threshold)+' units</strong></div>';
html+='<div class="kpis">'+card('Aggregate stock quantity',number(sum(v,'Stock')),'Movement aggregate proxy')+card('Observed stock pairs',number(v.length),'Warehouse and product')+card('Pairs below threshold',number(low.length),'Illustrative planning rule')+card('Observed products',number(products))+card('Warehouse records',number(distinct(v,'WarehouseID')),'Capacity is unavailable')+'</div>';
html+=grid(panel('Aggregate inventory by warehouse',bars(top(ws,15))),panel('Recorded on-time rate by warehouse',bars(top(group(s,'WarehouseID','RecordedOnTime','mean'),15),{pct:true}),'Service performance proxy, without a causal efficiency ranking.'));
html+='<div style="height:15px"></div>'+grid(panel('Lowest recorded warehouse-product aggregates',table(['Warehouse','Product','Units'],v.slice().sort((a,b)=>a.Stock-b.Stock).slice(0,8).map(r=>[r.WarehouseID,r.ProductID,number(r.Stock)]))),panel('Shipment workload per employee',bars(top(group(s,'WarehouseID').map(r=>({...r,value:r.value/DATA.Employees.filter(e=>e.WarehouseID===r.key).length})),15),{dec:1}),'Workload proxy over the selected order period. Staffing hours and handling costs are absent.'));
html+='<div class="callout limited">Inventory has no date, capacity or opening/closing balance. Quantity aggregates do not measure current stock, physical capacity utilisation or standard turnover. Month, customer city and order status filters do not apply to inventory quantities. Unobserved warehouse-product pairs remain unknown.</div>';}
if(active===3){html='<div class="kpis">'+card('Shipments',number(s.length),'Linked order cohort')+card('Recorded delayed',number(s.length-on),'Status label')+card('Recorded on-time rate',percent(on/s.length),'Delay 0-2 days')+card('Average recorded delay',number(sum(s,'DelayDays')/s.length,2)+' days')+card('Zero-delay share',percent(s.filter(r=>r.DelayDays===0).length/s.length),'Separate from on-time status')+'</div>';
html+=grid(panel('Delayed shipment rate by customer city',bars(top(group(s,'City','RecordedOnTime','mean').map(r=>({...r,value:1-r.value}))),{pct:true,color:'red',click:'city'}),'Customer city is the available destination proxy.'),panel('Recorded delay distribution',bars(group(s,'DelayDays').sort((a,b)=>a.key-b.key),{color:'orange'})));
html+='<div style="height:15px"></div>'+grid(panel('Shipments by order month',bars(group(s,'Month').sort((a,b)=>a.key.localeCompare(b.key))),'Order month is a cohort, not dispatch or arrival month.'),panel('Delivery status within order status',table(['Order status','Shipments','Recorded delayed'],['Delivered','Pending','Cancelled'].map(k=>[k,number(s.filter(r=>r.Status===k).length),number(s.filter(r=>r.Status===k&&!r.RecordedOnTime).length)])),'Shipment records exist for cancelled and pending orders. The source does not provide lifecycle timestamps.'));}
if(active===4){const product=group(i,'ProductID','DeliveredValue'),assoc=new Map();for(const r of i){if(!assoc.has(r.ProductID))assoc.set(r.ProductID,{all:new Set(),returned:new Set()});const a=assoc.get(r.ProductID);a.all.add(r.OrderID);if(r.HasReturn)a.returned.add(r.OrderID);}const rates=[...assoc].map(([key,a])=>({key,value:a.returned.size/a.all.size,count:a.all.size}));html='<div class="kpis">'+card('Products in selected orders',number(distinct(i,'ProductID')))+card('Delivered units',number(sum(delivered,'Quantity')))+card('Delivered value',number(value/1e6,2)+'m','Catalogue price units')+card('Supplier references',number(DATA.Suppliers.length),'Standalone catalogue')+card('Supplier score','Unavailable','No supplier-to-product link')+'</div>';
html+=grid(panel('Top products by delivered value',bars(top(product),{click:'product'}),'Select a product for its order and return association.'),panel('Delivered value by category',bars(top(group(delivered,'Category','LineValue')))));
html+='<div style="height:15px"></div>'+grid(panel('Products in orders associated with returns',bars(top(rates),{pct:true,color:'orange',click:'product'}),'This measures returned-order association. The returned item and quantity are absent, so actual product return rates cannot be calculated.'),panel('Supplier measurement coverage',table(['Measure','Coverage'],[['Supplier catalogue','150 reference records'],['Product / supplier mapping','Not supplied'],['Receipt and supplier dates','Not supplied'],['Supplier performance score','Not estimable']]),'No supplier assignment or performance ranking is inferred.'));}
$('content').innerHTML=html;window.currentMetrics={orders:o.length,deliveredValue:value,shipments:s.length,onTime:on,returnedOrders:ret.length,inventory:sum(v,'Stock'),lowStockPairs:v.filter(r=>r.Stock<threshold).length};}
function drill(kind,key){if(kind==='city'){$('city').value=key;render();return;}const d=subset();if(kind==='customer'){const o=d.o.filter(r=>r.CustomerID===key),i=d.i.filter(r=>r.CustomerID===key&&r.Status==='Delivered');$('detail-body').innerHTML='<h2>Customer '+key+'</h2><p>'+number(o.length)+' selected orders. Delivered catalogue value '+number(sum(i,'LineValue'),2)+'.</p>'+table(['Order','Date','Status','Whole order value'],o.slice().sort((a,b)=>a.OrderDate.localeCompare(b.OrderDate)).map(r=>[r.OrderID,r.OrderDate,r.Status,r.HasItems?number(r.OrderValue,2):'Unpriced']));}else{const i=d.i.filter(r=>r.ProductID===key),ids=new Set(i.map(r=>r.OrderID)),ret=new Set(i.filter(r=>r.HasReturn).map(r=>r.OrderID));$('detail-body').innerHTML='<h2>Product '+key+'</h2><p>Delivered catalogue value '+number(sum(i.filter(r=>r.Status==='Delivered'),'LineValue'),2)+'.</p><p>'+ret.size+' of '+ids.size+' associated orders have a return record ('+percent(ret.size/ids.size)+'). The return source does not identify the returned product.</p>'+table(['Order','Status','Units'],i.slice(0,12).map(r=>[r.OrderID,r.Status,r.Quantity]));}$('detail').showModal();}
$('reset').onclick=()=>{for(const k of Object.keys(filters()))$(k).value='';threshold=100;render();};$('save').onclick=()=>{try{localStorage.setItem('SwiftLogView',JSON.stringify({filters:filters(),active,threshold}));$('saved').textContent='View saved on this device';}catch(e){$('saved').textContent='View saving is unavailable in this browser';}};$('restore').onclick=()=>{try{const v=JSON.parse(localStorage.getItem('SwiftLogView'));if(!v){$('saved').textContent='No saved view';return;}for(const [k,x]of Object.entries(v.filters))$(k).value=x;active=v.active;threshold=v.threshold;render();$('saved').textContent='Saved view restored';}catch(e){$('saved').textContent='Saved view could not be read';}};render();
</script></body></html>'''
(ROOT / 'Dashboard').mkdir(exist_ok=True)
(ROOT / 'Dashboard' / 'SwiftLog_Dashboard.html').write_text(page)
print('Built five-page self-contained analytical dashboard.')
